mod blot;
mod canonical;
mod diagnostic;
pub mod extensions;
mod model;
mod program;
mod rust;
use anyhow::{Context, Result, bail, ensure};
use std::path::Path;

pub use program::{PROGRAM_MAGIC, PROGRAM_VERSION};

pub const SCHEMA: &str = include_str!("../../../protocol/schema.json");
/// What a game's Blot bindings, in its checkout's `pen/`, say they come from.
const HEADER: &str =
    "Generated by pen codegen from pen/protocol/schema.json:\nedit the schema and run `pen codegen`, not this file.";
/// What pen-protocol's packets.rs says it comes from.
const RUST_HEADER: &str =
    "Generated from protocol/schema.json by `just sync-protocol`:\nedit the schema and run that, not this file.";

/// The game's Blot bindings, as `generate` writes them: each file's name in
/// the checkout's `pen/`, and its source.
pub fn blot_bindings() -> Result<Vec<(&'static str, String)>> {
    let model = model::build(serde_json::from_str(SCHEMA).context("invalid protocol/schema.json")?)?;
    Ok(blot::emit(&model, HEADER))
}

/// What a game's bindings for its own events and sections say they come
/// from.
const EXTENSIONS_HEADER: &str = "Generated by pen codegen from this checkout's pen.json `protocol`:\ndeclare the game's events and sections there and run `pen codegen`, not this file.";

/// Writes the game's Blot bindings into `project`'s `pen/` (with
/// `extensions.blot` when its pen.json declares events or sections of its
/// own) and, given `rust_output`, pen-protocol's packets.rs (`pen codegen
/// --rust PATH`); with `check`, only says which of them are stale.
pub fn generate(project: &Path, rust_output: Option<&Path>, check: bool) -> Result<()> {
    let model = model::build(serde_json::from_str(SCHEMA).context("invalid protocol/schema.json")?)?;
    let rust = rust::emit(&model, RUST_HEADER);
    let mut outputs: Vec<_> =
        blot::emit(&model, HEADER).into_iter().map(|(name, source)| (project.join("pen").join(name), source)).collect();
    let declarations = extensions::Declarations::of_checkout(project)?;
    let declared = project.join("pen").join("extensions.blot");
    if declarations.is_empty() {
        // Bindings for declarations the checkout no longer has.
        if declared.is_file() {
            ensure!(
                !check,
                "stale generated protocol; run `pen codegen`:\n{} (pen.json declares nothing)",
                declared.display()
            );
            std::fs::remove_file(&declared).with_context(|| format!("remove {}", declared.display()))?;
        }
    } else {
        let header: Vec<_> = EXTENSIONS_HEADER.lines().map(|line| format!("// {line}")).collect();
        outputs.push((declared, extensions::emit(&declarations, &header)));
    }
    if let Some(path) = rust_output {
        outputs.push((path.to_owned(), rust));
    }
    let mut stale = Vec::new();
    for (path, contents) in &outputs {
        if std::fs::read_to_string(path).ok().as_ref() == Some(contents) {
            continue;
        }
        if check {
            stale.push(path.display().to_string());
        } else {
            if let Some(parent) = path.parent() {
                std::fs::create_dir_all(parent).with_context(|| format!("create {}", parent.display()))?;
            }
            std::fs::write(path, contents).with_context(|| format!("write {}", path.display()))?;
        }
    }
    if !stale.is_empty() {
        bail!(
            "stale generated protocol; run `pen codegen` (`just sync-protocol` in pen's checkout):\n{}",
            stale.join("\n")
        );
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    fn schema() -> Value {
        serde_json::from_str(SCHEMA).unwrap()
    }

    #[test]
    fn packet_contract_layout() {
        let model = model::build(schema()).unwrap();
        assert_eq!(model.magic, 0x474446);
        assert_eq!(model.header_lanes, 151);
        assert_eq!(model.event_lanes(), 5);
        assert_eq!(model.section("draws").fixed.as_ref().unwrap().lanes, 24);
        assert_eq!(model.section("insets").fixed.as_ref().unwrap().lanes, 48);
        assert_eq!(model.section("ui").head_lanes, 24);
        assert_eq!(model.section("poses").fixed.as_ref().unwrap().lanes, 4);
        assert_eq!(model.section("emitters").fixed.as_ref().unwrap().lanes, 42);
        // Position, reach, color, direction and a spot's two cosines.
        assert_eq!(model.section("lights").fixed.as_ref().unwrap().lanes, 12);
        assert_eq!(model.section("listener").fixed.as_ref().unwrap().lanes, 9);
        assert_eq!(model.section("panners").fixed.as_ref().unwrap().lanes, 15);
    }

    #[test]
    fn blot_bindings_own_their_nominal_types() {
        let model = model::build(schema()).unwrap();
        assert!(!SCHEMA.contains("\"blot\""));
        assert!(!SCHEMA.contains("gdev"));
        assert!(!SCHEMA.contains("packages/"));
        let sources = blot::emit(&model, HEADER);
        for (_, source) in &sources {
            for import in source.lines().filter(|line| line.starts_with("import ")) {
                let path = import.split('"').nth(1).unwrap();
                assert!(
                    ["std/array", "std/simd", "./lanes", "./protocol", "./protocol_render", "./types"].contains(&path),
                    "external binding dependency: {path}"
                );
            }
        }
        let render = &sources.iter().find(|(name, _)| *name == "protocol_render.blot").unwrap().1;
        assert!(render.contains("func (packet: types.RenderHeader)"));
        assert!(render.contains("func (draw: types.Draw)"));
        assert!(render.contains("draw.transform"));
        assert!(render.contains("inset.ambient.x"));
        assert!(render.contains("packet.clear.r"));
        assert!(render.contains("packet.clouds.drift.z"));
        let types = &sources.iter().find(|(name, _)| *name == "types.blot").unwrap().1;
        assert!(types.contains("transform: Mat4"));
        assert!(types.contains("parameters: Maybe Vec4"));
        assert!(types.contains("draws: &[Draw]"));
        assert!(types.contains("type RenderHeader ="));
        assert!(!types.contains("RenderFrame"));
        // Only tests import the canonical walks; no binding the game uses does.
        assert!(sources.iter().all(|(_, source)| !source.contains("./protocol_canonical")));
    }

    #[test]
    fn canonical_walks_cover_the_frame() {
        let model = model::build(schema()).unwrap();
        let rust = rust::emit(&model, RUST_HEADER);
        assert!(rust.contains("pub fn canonical_input(frame: &Frame, elapsed: f64, state: &[f32]) -> Vec<f32> {"));
        assert!(
            rust.contains("pub fn canonical_render(frame: &RenderFrame, schema: u32, state: &[f32]) -> Vec<f32> {")
        );
        let sources = blot::emit(&model, HEADER);
        let canonical = &sources.iter().find(|(name, _)| *name == "protocol_canonical.blot").unwrap().1;
        assert!(canonical.contains("const canonical_input = func (input: protocol.Input) => return do:"));
        assert!(canonical.contains("const render_packet_from_canonical = func (canonical: Array F32)"));
        // Every header lane and section is emitted into one named packet owner.
        for header in &model.header {
            let offset = header.laid.offset;
            assert!(canonical.contains(&format!("output[{offset}] :=")), "missing {}", header.key);
        }
        for section in &model.sections {
            let name = model::s(&section.section["name"]);
            assert!(canonical.contains(&format!("let {name}_start:")), "missing {name}");
        }
        assert!(!canonical.contains("RenderFrame"));
        assert!(canonical.contains("@storage.push extras canonical[at + index]"));
        assert!(canonical.contains("inset_draw_into canonical at children children extras"));
        // Each record's walk follows its fields; a group's sits where its first lane does.
        assert!(rust.contains(
            "out.extend([draw.mesh as f32, draw.material as f32]);\n        out.extend_from_slice(&draw.transform);"
        ));
        assert!(rust.contains("frame.aberration.y, frame.quality.msaa as f32"));
    }

    #[test]
    fn canonical_walks_take_a_group_that_may_be_absent() {
        // The schema has no group with a presence lane; Rust holds one as an Option,
        // the game's record as the lane: 0 for none, else the index plus one.
        let mut present = schema();
        present["render"]["header"]["sky.environment"] = serde_json::json!({"kind": "present", "to": "material"});
        let model = model::build(present).unwrap();
        let rust = rust::emit(&model, RUST_HEADER);
        assert!(rust.contains("pub sky: Option<Sky>,"));
        assert!(rust.contains("        match &frame.sky {\n            Some(sky) => {\n"));
        assert!(rust.contains("                    1.0, sky.zenith.x,"));
        assert!(rust.contains("            None => out.push(0.0),\n        }\n        out.extend([frame.fog.radius,"));
        assert!(rust.contains(" sky.environment as f32,\n"));
        let sources = blot::emit(&model, HEADER);
        let canonical = &sources.iter().find(|(name, _)| *name == "protocol_canonical.blot").unwrap().1;
        assert!(canonical.contains("  if present == 1:"));
        let environment = model.header.iter().find(|field| field.key == "sky.environment").unwrap().laid.offset;
        assert!(canonical.contains(&format!("    output[{environment}] := canonical[at] + 1.0")));
        assert!(canonical.contains("    @storage.push output 0.0"));
    }

    #[test]
    fn malformed_relationships_are_rejected() {
        let mut invalid = schema();
        invalid["render"]["sections"][0]["name"] = Value::String("unknown".into());
        assert!(model::build(invalid).is_err());
        let mut invalid = schema();
        invalid["input"]["events"][1]["tag"] = invalid["input"]["events"][0]["tag"].clone();
        assert!(model::build(invalid).is_err());
        let mut invalid = schema();
        invalid["input"]["events"][0]["value"]["lane"] = Value::String("missing".into());
        assert!(model::build(invalid).is_err());
        let mut invalid = schema();
        invalid["render"]["header"]["quality.msaa"]["kind"] = Value::String("unknown".into());
        assert!(model::build(invalid).is_err());
        let mut invalid = schema();
        invalid["render"]["sections"].as_array_mut().unwrap().reverse();
        assert!(model::build(invalid).is_err());
    }

    #[test]
    fn malformed_shapes_return_errors_without_panics() {
        fn visit(value: &Value, path: String, paths: &mut Vec<String>) {
            paths.push(path.clone());
            if let Some(object) = value.as_object() {
                for (key, child) in object {
                    visit(child, format!("{path}/{key}"), paths);
                }
            }
            if let Some(array) = value.as_array() {
                for (index, child) in array.iter().enumerate() {
                    visit(child, format!("{path}/{index}"), paths);
                }
            }
        }
        let original = schema();
        let mut paths = Vec::new();
        visit(&original, String::new(), &mut paths);
        for path in paths {
            for replacement in [Value::Null, Value::Bool(false)] {
                let mut invalid = original.clone();
                *invalid.pointer_mut(&path).unwrap() = replacement;
                let result = std::panic::catch_unwind(|| {
                    if let Ok(model) = model::build(invalid) {
                        rust::emit(&model, RUST_HEADER);
                        blot::emit(&model, HEADER);
                    }
                });
                assert!(result.is_ok(), "malformed schema panicked at {path}");
            }
        }
    }

    #[test]
    fn freshness_check_detects_edits_and_missing_outputs() {
        let dir = std::env::temp_dir().join(format!("pen-codegen-test-{}", std::process::id()));
        let rust = dir.join("packets.rs");
        generate(&dir, Some(&rust), false).unwrap();
        generate(&dir, Some(&rust), true).unwrap();
        std::fs::write(&rust, "stale").unwrap();
        assert!(generate(&dir, Some(&rust), true).is_err());
        assert_eq!(std::fs::read_to_string(&rust).unwrap(), "stale");
        std::fs::remove_file(dir.join("pen/types.blot")).unwrap();
        assert!(generate(&dir, None, true).is_err());
        generate(&dir, Some(&rust), false).unwrap();
        generate(&dir, Some(&rust), true).unwrap();
        std::fs::remove_dir_all(&dir).unwrap();
    }
}
